from ..objects.mosaiq_plan_promoting_objects import PlanPromoting
from interops.libraries.squish_actions import CommonActions

def __find_edit_course_data_dialog() -> bool:
    """Searches for main Edit Course Data Dialog. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the edit_course_data.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(PlanPromoting.editCourse_Data_Dialog) is not None else False

def get_course_id_promote_data() -> str:
    """Locates the Edit Course Data Dialog UI > Locates the Course ID row within the item list view and grabs all the child objects >
    returns the text value of the Course IDs Promote Data column.

    :raises RuntimeError: This raises if the Edit Course Data Dialog UI isn't found.
    :return: String value of the Course ID text value in the Promote Data column
    :rtype: str
    """
    minimum_number_of_active_cells_in_row = 3

    if __find_edit_course_data_dialog() is False:
        raise RuntimeError("Edit Course Dialog was not open at the time get_course_id_promote_data() was called.")
    course_id_row_active_cells = CommonActions.get_child_objects(PlanPromoting.editCourse_Data_CourseID_ListViewItem)
    if course_id_row_active_cells is None or len(course_id_row_active_cells) < minimum_number_of_active_cells_in_row:
        raise RuntimeError("Invalid Course ID object found. Course ID List View could either not be visible or no data was populated within")
    return CommonActions.get_objects_text_value(course_id_row_active_cells[2]) #type: ignore

def set_course_id_promote_data(courseID: str) -> None:
    """Locates the Edit Course Data Dialog UI > Locates the Course ID row within the item list view and grabs all the child objects >
    then types in the given courseID string into the Promote Data field

    :param str courseID: String value of the value that will be entered into the Promote Data box of the Course ID.
    :raises RuntimeError: This raises if the Edit Course Data Dialog UI isn't found.
    :rtype: str
    """
    minimum_number_of_active_cells_in_row = 3

    if __find_edit_course_data_dialog() is False:
        raise RuntimeError("Edit Course Dialog was not open at the time set_course_id_promote_data() was called.")
    course_id_row_active_cells = CommonActions.get_child_objects(PlanPromoting.editCourse_Data_CourseID_ListViewItem)
    if course_id_row_active_cells is None or len(course_id_row_active_cells) < minimum_number_of_active_cells_in_row:
        raise RuntimeError("Invalid Course ID object found. Course ID List View could either not be visible or no data was populated within")
    CommonActions.type_in_textfield(course_id_row_active_cells[2], courseID) #type: ignore
    CommonActions.press_enter_key()
